// Огненное поле: тепло поднимается от основания ленты
animation "Procedural Fire" {
  state heat = array(300, 0);

  update(dt) {
    for (let i = 0; i < 300; i += 1) {
      let base = noise(i * 0.075, time * 1.8);
      let pulse = noise(i * 0.035 + 13, time * 3.1);
      let source = max(0, 1 - i / 85);
      heat[i] = clamp(heat[i] * 0.88 + base * source * 0.72 + pulse * source * 0.2, 0, 1);
    }
  }

  render(i) {
    let h = clamp(heat[i] * 1.55, 0, 1);
    let red = clamp(h * 2.6, 0, 1);
    let green = clamp((h - 0.22) * 2.0, 0, 1);
    let blue = clamp((h - 0.82) * 4.0, 0, 0.35);
    return rgb(red, green * 0.72, blue);
  }
}

// Перекрывающиеся волны и световые гребни
animation "Ocean Waves" {
  render(i) {
    let x = i / 299;
    let waveA = sin(x * 18 - time * 2.2);
    let waveB = sin(x * 31 + time * 1.35 + 0.8);
    let swell = sin(x * 5.5 - time * 0.65);
    let n = noise(x * 9, time * 0.8);
    let surface = waveA * 0.28 + waveB * 0.16 + swell * 0.2 + n * 0.18;
    let foam = smoothstep(0.43, 0.68, surface + noise(x * 37, time * 2.4) * 0.25);
    let deep = rgb(0.005, 0.045, 0.12);
    let water = rgb(0.015, 0.24, 0.42);
    let crest = rgb(0.42, 0.82, 0.92);
    return mix(mix(deep, water, clamp(0.42 + surface, 0, 1)), crest, foam * 0.82);
  }
}

// Медленные цветовые ленты северного сияния
animation "Aurora Flow" {
  render(i) {
    let x = i / 299;
    let curtain = sin(x * 8 + time * 0.55 + sin(x * 17 - time * 0.3) * 0.8);
    let folds = noise(x * 4.5 + time * 0.12, time * 0.22);
    let band = smoothstep(-0.15, 0.8, curtain * 0.55 + folds * 0.75);
    let hue = 0.38 + 0.28 * sin(x * 4.8 - time * 0.18);
    let glow = band * (0.28 + 0.72 * noise(x * 12, time * 0.45));
    return hsv(hue, 0.82, glow);
  }
}

// Радужная волна с движущимся спектром
animation "Rainbow Flow" {
  render(i) {
    let x = i / 299;
    let hue = fract(x * 1.35 - time * 0.12);
    let wave = 0.55 + 0.45 * sin(x * 22 - time * 3.2);
    let shimmer = 0.82 + 0.18 * noise(x * 45, time * 2.0);
    return hsv(hue, 0.94, wave * shimmer);
  }
}

// Случайные вспышки, затухающие вдоль ленты
animation "Spark Field" {
  state sparks = array(300, 0);

  update(dt) {
    for (let i = 0; i < 300; i += 1) {
      let hit = random() > 0.992 ? random() : 0;
      sparks[i] = max(0, sparks[i] - dt * 1.7) + hit;
      sparks[i] = clamp(sparks[i], 0, 1);
    }
  }

  render(i) {
    let glow = sparks[i];
    let ambient = noise(i * 0.06, time * 0.7) * 0.035;
    return rgb(clamp(ambient + glow, 0, 1), clamp(ambient * 0.35 + glow * 0.48, 0, 1), clamp(glow * 0.08, 0, 1));
  }
}

// HEARTBEAT — два быстрых удара с мягким затуханием между ними
animation "Heartbeat" {
  render(i) {
    let phase = fract(time / 1.35);
    let first = exp(-pow((phase - 0.12) / 0.045, 2));
    let second = exp(-pow((phase - 0.27) / 0.055, 2));
    let beat = clamp(first * 1.0 + second * 0.88, 0, 1);
    let body = 0.18 + beat * 0.82;
    let whitePeak = smoothstep(0.72, 0.98, beat);
    let red = 0.48 * body + 0.52 * whitePeak;
    let green = 0.015 * body + 0.985 * whitePeak;
    let blue = 0.12 * body + 0.88 * whitePeak;
    return rgb(red, green, blue);
  }
}

// EVENT HORIZON — свет закручивается вокруг тёмного центра и выбрасывается наружу
animation "Event Horizon" {
  render(i) {
    let center = 150 + sin(time * 0.19) * 13;
    let d = abs(i - center);
    let ring = exp(-pow((d - 18 - sin(time * 1.7 + i * 0.035) * 3) / 4.2, 2));
    let inner = exp(-pow(d / 8, 2));
    let jet = exp(-pow((d - 39) / 7, 2)) * pow(max(0, sin(time * 0.72 - d * 0.045)), 5);
    let stars = pow(noise(i * 0.31, 7.2), 18) * 0.18;
    let r = ring * 0.2 + jet * 0.38 + stars * 0.25;
    let g = ring * 0.34 + jet * 0.16 + stars * 0.45;
    let b = ring * 0.95 + jet * 0.8 + stars;
    let shadow = 1 - inner * 0.98;
    return rgb(r * shadow, g * shadow, b * shadow);
  }
}

// REACTOR CORE — ядро накапливает энергию, перегревается и сбрасывает заряд
animation "Reactor Core" {
  state charge = 0.12;
  state heat = 0;
  update(dt) {
    charge += dt * (0.22 + heat * 0.08);
    if (charge > 1) {
      charge = 0;
      heat = 1;
    }
    heat = max(0, heat - dt * 0.42);
  }
  render(i) {
    let d = abs(i - 149.5) / 150;
    let pulse = pow(max(0, sin(time * 5.2 - d * 5)), 8);
    let core = clamp((1 - d) * (0.28 + charge * 0.9) + pulse * 0.35, 0, 1);
    let flash = heat * (0.35 + 0.65 * pulse);
    return rgb(clamp(core * 1.4 + flash, 0, 1), clamp(core * 0.38 + flash * 0.88, 0, 1), clamp(core * 0.025 + flash, 0, 1));
  }
}

// LIQUID MERCURY — вязкие металлические капли сливаются и расходятся
animation "Liquid Mercury" {
  render(i) {
    let x = i / 299;
    let a = 0.22 + 0.5 * (0.5 + 0.5 * sin(time * 0.63));
    let b = 0.72 + 0.42 * (0.5 + 0.5 * sin(time * 0.47 + 2.1));
    let p1 = exp(-pow((x - a) / 0.075, 2));
    let p2 = exp(-pow((x - b) / 0.11, 2));
    let bridge = exp(-pow((x - (a + b) * 0.5) / (0.08 + abs(a - b) * 0.12), 2)) * 0.32;
    let metal = clamp(p1 + p2 + bridge, 0, 1);
    let ripple = pow(max(0, sin(x * 48 - time * 2.8 + sin(x * 13 + time) * 2)), 12) * metal;
    let shine = clamp(metal * 0.42 + ripple * 0.8, 0, 1);
    return rgb(shine * 0.82 + metal * 0.12, shine * 0.91 + metal * 0.15, shine + metal * 0.2);
  }
}

// PLASMA DISCHARGE — электрические разряды с ветвящимися вспышками
animation "Plasma Discharge" {
  state sparks = array(300, 0);
  state branches = array(300, 0);
  update(dt) {
    for (let i = 0; i < 300; i += 1) {
      let hit = random() > 0.993 ? randomRange(0.65, 1) : 0;
      sparks[i] = max(0, sparks[i] - dt * randomRange(2.8, 5.2)) + hit;
      branches[i] = max(0, branches[i] - dt * 2.1);
      if (hit > 0.5) {
        if (i > 0) {
          branches[i - 1] = max(branches[i - 1], 0.8);
        }
        if (i < 299) {
          branches[i + 1] = max(branches[i + 1], 0.8);
        }
      }
      sparks[i] = clamp(sparks[i], 0, 1);
    }
  }
  render(i) {
    let glow = clamp(sparks[i] + branches[i] * 0.45, 0, 1);
    let after = noise(i * 0.12, time * 1.8) * 0.025;
    return rgb(clamp(after * 0.35 + glow * 0.72, 0, 1), clamp(after + glow * 0.82, 0, 1), clamp(after * 2 + glow, 0, 1));
  }
}

// BIOLUMINESCENCE — живые огни пробуждают соседей цепной реакцией
animation "Bioluminescence" {
  state life = array(300, 0);
  update(dt) {
    for (let i = 0; i < 300; i += 1) {
      let left = i > 0 ? life[i - 1] : 0;
      let right = i < 299 ? life[i + 1] : 0;
      let seed = random() > 0.997 ? randomRange(0.55, 1) : 0;
      life[i] = max(0, life[i] - dt * 0.34) + seed + max(left, right) * dt * 0.72;
      life[i] = clamp(life[i], 0, 1);
    }
  }
  render(i) {
    let glow = pow(life[i], 1.7);
    let shimmer = 0.7 + 0.3 * sin(time * 2.4 + i * 0.17);
    return rgb(glow * 0.08, glow * 0.72 * shimmer, glow * 0.48 + glow * 0.42 * shimmer);
  }
}

// SOLAR ECLIPSE — затмение оставляет корону, затем вспыхивает солнечный край
animation "Solar Eclipse" {
  render(i) {
    let phase = fract(time / 12);
    let cover = phase < 0.58 ? smoothstep(0.08, 0.58, phase) : 1 - smoothstep(0.58, 0.94, phase);
    let x = i / 299;
    let edge = abs(x - 0.5);
    let corona = exp(-pow((edge - (0.12 + cover * 0.035)) / 0.025, 2));
    let disk = (1 - smoothstep(0.085, 0.13, edge)) * (1 - cover);
    let flare = pow(max(0, sin(time * 0.8 + i * 0.035)), 16) * corona;
    let gold = corona * (0.5 + cover * 0.5) + disk + flare;
    return rgb(clamp(gold, 0, 1), clamp(gold * 0.48 + flare * 0.4, 0, 1), clamp(disk * 0.12 + corona * 0.06 + flare, 0, 1));
  }
}

// DEEP SIGNAL — импульс уходит в темноту, а удалённые узлы отвечают эхом
animation "Deep Signal" {
  render(i) {
    let x = i / 299;
    let travel = fract(time * 0.16);
    let wave = exp(-pow((x - travel) / 0.025, 2));
    let echoA = exp(-pow((x - fract(travel + 0.31)) / 0.018, 2)) * 0.55;
    let echoB = exp(-pow((x - fract(travel + 0.67)) / 0.03, 2)) * 0.28;
    let carrier = noise(i * 0.045, 3.7) * 0.035;
    let pulse = clamp(wave + echoA + echoB, 0, 1);
    return rgb(carrier * 0.12 + pulse * 0.28, carrier + pulse * 0.95, carrier * 0.28 + pulse * 0.18);
  }
}

// DREAM STATE — цветовые потоки распадаются на светящиеся острова и сливаются
animation "Dream State" {
  render(i) {
    let x = i / 299;
    let flow = sin(x * 9 - time * 0.34 + sin(x * 19 + time * 0.18) * 1.4);
    let islands = pow(max(0, sin(x * 23 + time * 0.27 + noise(x * 5, time * 0.12))), 5);
    let veil = smoothstep(-0.55, 0.8, flow) * 0.32;
    let glow = clamp(veil + islands * 0.72, 0, 1);
    let hue = fract(0.34 + 0.22 * sin(x * 3.5 - time * 0.09) + islands * 0.12);
    return hsv(hue, 0.72, glow);
  }
}

// STARFORGE — рождение звезды: коллапс, сверхновая и пульсар
animation "Starforge" {
  state seed = random();
  state cycle = randomRange(16, 21);
  render(i) {
    let t = fract(time / cycle) * cycle;
    let cycleIndex = floor(time / cycle);
    let center = 132 + noise(cycleIndex * 17.13 + seed * 31, seed * 73 + 5.1) * 36;
    let shellWidth = 2.4 + noise(cycleIndex * 19.7 + seed * 13, seed * 29 + 1.7) * 2.8;
    let cloudScale = 0.035 + noise(cycleIndex * 23.9 + seed * 47, seed * 11 + 8.3) * 0.05;
    let cloudOffset = noise(cycleIndex * 29.3 + seed * 19, seed * 61 + 2.9) * 1000;
    let blastReach = 126 + noise(cycleIndex * 31.1 + seed * 37, seed * 17 + 6.2) * 32;
    let asymmetry = 0.08 + noise(cycleIndex * 37.7 + seed * 23, seed * 43 + 3.4) * 0.24;
    let starDensity = 15 + noise(cycleIndex * 41.3 + seed * 53, seed * 7 + 9.1) * 14;
    let pulseRate = 2.2 + noise(cycleIndex * 43.9 + seed * 41, seed * 31 + 4.6) * 2.2;
    let gatherWidth = 10 + noise(cycleIndex * 47.1 + seed * 11, seed * 59 + 7.8) * 4;
    let coreWidth = 3.1 + noise(cycleIndex * 53.3 + seed * 67, seed * 13 + 2.2) * 1.3;
    let shockWidth = 3.5 + noise(cycleIndex * 59.9 + seed * 7, seed * 37 + 8.6) * 3.5;
    let cloudRadius = 88 + noise(cycleIndex * 61.7 + seed * 29, seed * 47 + 1.3) * 40;
    let side = i < center ? -1 : 1;
    let shapeNoise = noise(i * 0.023 + seed * 41, seed * 73 + 5.1);
    let d = abs(i - center) * (1 + side * asymmetry * (shapeNoise - 0.5));
    let fade = smoothstep(0, 0.7, t);
    let star = pow(noise(i * 0.41 + seed * 31, seed * 100 + cloudOffset), starDensity) * 0.28;
    let r = star * 0.42;
    let g = star * 0.58;
    let b = star * 0.9;
    let collapse = smoothstep(4, 8, t);
    let shell = exp(-pow((d - blastReach * (1 - collapse)) / shellWidth, 2));
    let gather = exp(-pow(d / gatherWidth, 2)) * collapse;
    let coreGlow = exp(-pow(d / coreWidth, 2)) * smoothstep(8, 8.85, t) * (1 - smoothstep(8.9, 9.1, t));
    let blast = smoothstep(9, 12, t);
    let shock = exp(-pow((d - blast * blastReach) / shockWidth, 2)) * smoothstep(9, 9.4, t);
    let remnant = smoothstep(12, 12.5, t) * (1 - smoothstep(16.2, 18, t));
    let dustReveal = smoothstep(d - 7, d + 7, blast * blastReach) * smoothstep(9, 9.4, t);
    let dustFade = 1 - smoothstep(16.2, 18, t);
    let cloud = noise(i * cloudScale + seed * 17, seed * 100 + cloudOffset + 27.3) * exp(-pow(d / cloudRadius, 2)) * dustReveal * dustFade;
    let pulse = exp(-pow(d / 5.5, 2)) * remnant * (0.35 + 0.65 * pow(max(0, sin((t - 12) * pulseRate)), 10));
    r += coreGlow * 0.22 + shell * (1 - collapse) * 0.55 + gather * 0.42 + coreGlow + shock + cloud * 0.48 + pulse * 0.95;
    g += coreGlow * 0.1 + shell * (1 - collapse) * 0.26 + gather * 0.2 + coreGlow * 0.96 + shock * 0.72 + cloud * 0.2 + pulse * 0.72;
    b += coreGlow * 0.03 + shell * (1 - collapse) * 0.04 + gather * 0.035 + coreGlow * 0.82 + shock * 0.28 + cloud * 0.12 + pulse * 0.38;
    return rgb(clamp(r * fade, 0, 1), clamp(g * fade, 0, 1), clamp(b * fade, 0, 1));
  }
}

// Метеорный поток: независимые частицы с яркой головой и затухающим хвостом
animation "Meteor Shower" {
  state heads = array(7, 0);
  state speeds = array(7, 0);
  state lengths = array(7, 0);
  state hues = array(7, 0);

  update(dt) {
    for (let j = 0; j < 7; j += 1) {
      // First frame: distribute meteors across the strip so motion is visible immediately.
      if (speeds[j] <= 0) {
        heads[j] = randomRange(0, 299);
        speeds[j] = randomRange(75, 125);
        lengths[j] = randomRange(18, 46);
        hues[j] = randomRange(0.53, 0.62);
      }

      heads[j] += speeds[j] * dt;

      // Re-enter just before LED 0; never wait several seconds off-strip.
      if (heads[j] > 320) {
        heads[j] = -randomRange(0, 38);
        speeds[j] = randomRange(75, 125);
        lengths[j] = randomRange(18, 46);
        hues[j] = randomRange(0.53, 0.62);
      }
    }
  }

  render(i) {
    let r = 0.001;
    let g = 0.003;
    let b = 0.012;

    // Slowly moving deep-space background, intentionally very dim.
    let haze = noise(i * 0.025, time * 0.16);
    b += haze * 0.018;
    g += haze * 0.005;

    // Small distant stars.
    let star = pow(noise(i * 0.73, 19.7), 24);
    r += star * 0.16;
    g += star * 0.22;
    b += star * 0.34;

    for (let j = 0; j < 7; j += 1) {
      let d = heads[j] - i;
      if (d >= 0 && d < lengths[j]) {
        let tail = exp(-d * 0.105);
        let taper = 1 - d / lengths[j];
        let power = clamp(tail * taper * 0.9, 0, 1);
        let meteor = hsv(hues[j], 0.42, power);
        let hotHead = exp(-d * 0.9);

        r += meteor[0] + hotHead * 0.8;
        g += meteor[1] + hotHead * 0.82;
        b += meteor[2] + hotHead * 0.95;
      }
    }

    return rgb(clamp(r, 0, 1), clamp(g, 0, 1), clamp(b, 0, 1));
  }
}

// THE LAST LIGHTHOUSE — ночной шторм, проходящий луч маяка и корабль, ищущий гавань
animation "The Last Lighthouse" {
  state shipX = -24;
  state stormFlash = 0;
  state stormTimer = 5;
  state arrivalGlow = 0;

  update(dt) {
    // Маленький корабль медленно пересекает ночное море.
    shipX += dt * 13;
    if (shipX > 274) {
      shipX = -24;
      arrivalGlow = 1;
    }

    // Гавань некоторое время светится после прибытия корабля.
    arrivalGlow = max(0, arrivalGlow - dt * 0.24);

    // Молнии запускаются по таймеру, независимо от FPS.
    stormFlash = max(0, stormFlash - dt * 2.7);
    stormTimer -= dt;
    if (stormTimer <= 0) {
      stormFlash = randomRange(0.65, 1.0);
      stormTimer = randomRange(4, 9);
    }
  }

  render(i) {
    let x = i / 299;

    // Ночное небо и глубокая вода.
    let swellA = sin(i * 0.052 - time * 1.35);
    let swellB = sin(i * 0.091 + time * 0.82 + 1.7);
    let waterNoise = noise(i * 0.035, time * 0.55);
    let wave = swellA * 0.5 + swellB * 0.28 + waterNoise * 0.42;
    let waterLevel = clamp(0.13 + wave * 0.11, 0.025, 0.42);

    let r = 0.002 + waterLevel * 0.025;
    let g = 0.008 + waterLevel * 0.12;
    let b = 0.025 + waterLevel * 0.27;

    // Лунные блики на гребнях волн.
    let foam = smoothstep(0.38, 0.72, wave + noise(i * 0.16, time * 1.8) * 0.32);
    r += foam * 0.11;
    g += foam * 0.31;
    b += foam * 0.43;

    // Вращающийся луч остаётся привязанным к лампе: мягко вырастает
    // влево, втягивается в источник, затем так же раскрывается вправо.
    let beamPhase = fract(time / 8);
    let beamDirection = -1;
    let beamLength = 0;
    if (beamPhase < 0.25) {
      beamLength = 42 * smoothstep(0, 1, beamPhase / 0.25);
    } else {
      if (beamPhase < 0.5) {
        beamLength = 42 * (1 - smoothstep(0, 1, (beamPhase - 0.25) / 0.25));
      } else {
        beamDirection = 1;
        if (beamPhase < 0.75) {
          beamLength = 15 * smoothstep(0, 1, (beamPhase - 0.5) / 0.25);
        } else {
          beamLength = 15 * (1 - smoothstep(0, 1, (beamPhase - 0.75) / 0.25));
        }
      }
    }
    let beamDistance = (i - 282) * beamDirection;
    let beamMask = beamDistance > 0 ? 1 : 0;
    let beamFade = clamp(1 - beamDistance / (beamLength + 1), 0, 1) * smoothstep(0, 5, beamDistance) * beamMask;
    let beamFlicker = 0.97 + 0.03 * sin(time * 2.1);
    r += beamFade * 0.34 * beamFlicker;
    g += beamFade * 0.24 * beamFlicker;
    b += beamFade * 0.055 * beamFlicker;

    // Сам маяк и тёплые огни гавани справа.
    let lighthouse = exp(-abs(i - 286) * 0.22);
    let lamp = exp(-abs(i - 282) * 0.72);
    r += lighthouse * 0.09 + lamp * 0.9;
    g += lighthouse * 0.12 + lamp * 0.58;
    b += lighthouse * 0.17 + lamp * 0.18;

    let harbor = exp(-pow((i - 266) / 17, 2)) * arrivalGlow;
    r += harbor * 0.55;
    g += harbor * 0.24;
    b += harbor * 0.055;

    // Корабль: тёплый корпус и яркий навигационный огонь.
    let shipBody = exp(-abs(i - shipX) * 0.72);
    let shipLamp = exp(-pow((i - shipX) / 1.8, 2));
    r += shipBody * 0.24 + shipLamp * 0.95;
    g += shipBody * 0.12 + shipLamp * 0.56;
    b += shipBody * 0.055 + shipLamp * 0.12;

    // Гроза кратко освещает всё море холодным бело-синим светом.
    let lightning = stormFlash * (0.55 + 0.45 * noise(i * 0.12, 8.3));
    r += lightning * 0.24;
    g += lightning * 0.38;
    b += lightning * 0.62;

    return rgb(clamp(r, 0, 1), clamp(g, 0, 1), clamp(b, 0, 1));
  }
}
